        margin: 0 0 0.5rem;
        font-size: clamp(1.75rem, 4vw, 2.5rem);
        line-height: 1.1;
        letter-spacing: -0.03em;
      }

      .lede {
        margin: 0 0 1.5rem;
        color: var(--muted);
        max-width: 60ch;
      }

      .form-field {
        background: var(--panel-2);
        border: 1px solid var(--border);
        border-radius: 1.25rem;
        padding: 1.25rem;
      }

