        display: flex;
        align-items: center;
        gap: 0.875rem;
        padding: 0.9rem 1rem;
        border-radius: 0.95rem;
        border: 1px solid var(--border);
        background: rgba(255, 255, 255, 0.02);
        cursor: pointer;
        transition: border-color 160ms ease, background-color 160ms ease, transform 160ms ease;
