                        label: "Push Notifications",
                      })}
                    </div>
                  </fieldset>
                </div>

                <div class="actions">
                  <button type="submit">Submit</button>
                </div>
              </form>
            </section>
          </div>
        </main>
      `;

      document.getElementById("app").innerHTML = NotificationPreferenceForm();
    </script>
  </body>
